1	//! HTTP 接口集成测试：通过真实 TCP 连接访问 axum 服务，
2	//! 覆盖健康/版本接口、写入校验、版本快照、重启恢复与并发场景。
3	
4	use super::app;
5	use crate::store::Store;
6	use std::io::{Read, Write};
7	use std::net::TcpStream;
8	use std::sync::Arc;
9	
10	use serde_json::{Value, json};
11	
12	struct TestServer {
13	    addr: String,
14	    _dir: tempfile::TempDir,
15	}
16	
17	mod tempfile {
18	    //! 极简临时目录（避免引入额外依赖）。
19	    use std::path::PathBuf;
20	    use std::sync::atomic::{AtomicU64, Ordering};
21	    use std::time::{SystemTime, UNIX_EPOCH};
22	
23	    static SEQ: AtomicU64 = AtomicU64::new(0);
24	
25	    pub struct TempDir(pub PathBuf);
26	    impl TempDir {
27	        pub fn new() -> Self {
28	            let nanos = SystemTime::now()
29	                .duration_since(UNIX_EPOCH)
30	                .unwrap()
31	                .as_nanos();
32	            let pid = std::process::id();
33	            // 全局递增序号，杜绝同纳秒内并发创建导致的目录名撞车。
34	            let seq = SEQ.fetch_add(1, Ordering::Relaxed);
35	            let dir = std::env::temp_dir().join(format!("vde-http-{pid}-{nanos}-{seq}"));
36	            std::fs::create_dir_all(&dir).unwrap();
37	            TempDir(dir)
38	        }
39	        pub fn path(&self) -> &std::path::Path {
40	            &self.0
41	        }
42	    }
43	    impl Drop for TempDir {
44	        fn drop(&mut self) {
45	            let _ = std::fs::remove_dir_all(&self.0);
46	        }
47	    }
48	}
49	
50	async fn spawn_server() -> TestServer {
51	    let dir = tempfile::TempDir::new();
52	    let store = Arc::new(Store::open(dir.path()).unwrap());
53	    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
54	    let addr = listener.local_addr().unwrap().to_string();
55	    tokio::spawn(async move {
56	        axum::serve(listener, app(store)).await.unwrap();
57	    });
58	    TestServer { addr, _dir: dir }
59	}
60	
61	struct RawResponse {
62	    status: u16,
63	    body: Value,
64	}
65	
66	fn request(addr: &str, method: &str, path: &str, body: Option<&str>) -> RawResponse {
67	    let mut stream = TcpStream::connect(addr).unwrap();
68	    let mut req = format!("{method} {path} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n");
69	    if let Some(b) = body {
70	        req.push_str("Content-Type: application/json\r\n");
71	        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
72	    }
73	    req.push_str("\r\n");
74	    if let Some(b) = body {
75	        req.push_str(b);
76	    }
77	    stream.write_all(req.as_bytes()).unwrap();
78	    let mut raw = String::new();
79	    stream.read_to_string(&mut raw).unwrap();
80	    let split = raw.find("\r\n\r\n").unwrap();
