354	    let writers = 8usize;
355	    let batches = 12usize;
356	    let batch_size = 5usize;
357	
358	    let mut handles = Vec::new();
359	    for w in 0..writers {
360	        let addr = s.addr.clone();
361	        handles.push(tokio::spawn(async move {
362	            for b in 0..batches {
363	                let mut recs = String::from("[");
364	                for i in 0..batch_size {
365	                    if i > 0 {
366	                        recs.push(',');
367	                    }
368	                    recs.push_str(&format!(
369	                        "{{\"id\":\"w{w}-b{b}-r{i}\",\"w\":{w},\"b\":{b},\"i\":{i}}}"
370	                    ));
371	                }
372	                recs.push(']');
373	                let payload = format!(r#"{{"records":{recs}}}"#);
374	                let addr2 = addr.clone();
375	                let r = tokio::task::spawn_blocking(move || {
376	                    request(&addr2, "POST", "/collections/items/records", Some(&payload))
377	                })
378	                .await
379	                .unwrap();
380	                assert_eq!(r.status, 200, "batch {w}/{b}: {}", r.body);
381	            }
382	        }));
383	    }
