/// 比较两个已保存版本中同一集合的差异。只读，不生成新版本、不改写任何记录。
///
/// - `start` 为起始版本，`target` 为目标版本，二者可相同（此时三个列表均为空）；
/// - 起始版本晚于目标版本返回 `StartAfterTarget`（HTTP 400）；
/// - 任一版本或集合不存在返回相应的 not-found 错误（HTTP 404）。
///
/// 三个结果列表均按主键 id 的字节序升序排列；记录内容比较忽略字段顺序，
/// 字段名与字段值相同即视为同一条记录。
pub fn diff_records(
    &self,
    start: u64,
    target: u64,
    collection: &str,
) -> Result<DiffOutcome, DiffError> {
    let st = self.inner.lock().unwrap();

    // 定位两个版本。版本按保存动作顺序保存在 Vec 中，位置先后即时间先后。
    let mut start_pos = None;
    let mut target_pos = None;
    for (pos, v) in st.versions.iter().enumerate() {
        if v.id == start {
            start_pos = Some(pos);
        }
        if v.id == target {
            target_pos = Some(pos);
        }
    }
    let start_pos = start_pos.ok_or(DiffError::StartVersionNotFound)?;
    let target_pos = target_pos.ok_or(DiffError::TargetVersionNotFound)?;
    if start_pos > target_pos {
        return Err(DiffError::StartAfterTarget);
    }

    let start_records = st.versions[start_pos]
        .data
        .get(collection)
        .ok_or(DiffError::StartCollectionNotFound)?;
    let target_records = st.versions[target_pos]
        .data
        .get(collection)
        .ok_or(DiffError::TargetCollectionNotFound)?;

    // 用 BTreeMap 以 id 字节序排列，产出时自然有序；值保留完整记录。
    let start_map: BTreeMap<&str, &Record> = start_records
        .iter()
        .map(|r| (r["id"].as_str().expect("validated record"), r))
        .collect();
    let target_map: BTreeMap<&str, &Record> = target_records
        .iter()
        .map(|r| (r["id"].as_str().expect("validated record"), r))
        .collect();

    let mut added = Vec::new();
    let mut dropped = Vec::new();
    let mut changed = Vec::new();

    // 并集遍历：BTreeMap 的键已按字节序排序，分别扫描即可保证输出有序。
    for (id, rec) in &start_map {
        match target_map.get(id) {
            None => added.push((*rec).clone()),
            Some(new) => {
                // serde_json 的 Map 为保序 Map，但其 PartialEq 与字段顺序无关。
                if *rec != *new {
                    changed.push(ChangedRecord {
                        before: (*rec).clone(),
                        after: (*new).clone(),
                    });
                }
            }
        }
    }
    for (id, rec) in &target_map {
        if !start_map.contains_key(id) {
            dropped.push((*rec).clone());
        }
    }

    Ok(DiffOutcome {
        start_version: start,
        target_version: target,
        collection: collection.to_string(),
        added,
        dropped,
        changed,
    })
}

