    #[test]
    fn diff_reports_added_dropped_changed_ignoring_field_order() {
        let dir = temp_dir();

        // 起始版本 v1：u1（之后被改）、u2（之后被删）、u3（始终不变）。
        let v1;
        {
            let store = Store::open(&dir).unwrap();
            store
                .write_batch(
                    "users",
                    &[
                        json!({"id": "u1", "name": "Ada", "age": 36}),
                        json!({"id": "u2", "name": "Lin"}),
                        json!({"id": "u3", "name": "Same", "nested": {"a": 1, "b": 2}}),
                    ],
                )
                .unwrap();
            v1 = store.save_version().unwrap().id;
            // v1 之后新写入 u4。
            store
                .write_batch("users", &[json!({"id": "u4", "name": "New"})])
                .unwrap();
        }

        // 直接改写 snapshot.json 中“当前数据”区段（模拟经外部校正/备份恢复后的分叉状态）：
        // 删除 u2、改写 u1、新增 u5，再重开保存为 v3。版本区段 v1 保持只读不变。
        let snap_path = dir.join("snapshot.json");
        let mut state: Value =
            serde_json::from_slice(&fs::read(&snap_path).unwrap()).unwrap();
        let recs = state["collections"][0]["records"].as_array_mut().unwrap();
        recs.retain(|r| r["id"] != "u2");
        for r in recs.iter_mut() {
            if r["id"] == "u1" {
                *r = json!({"id": "u1", "name": "Ada", "age": 37, "role": "admin"});
            }
        }
        recs.push(json!({"id": "u5", "name": "Later"}));
        let mut bytes = serde_json::to_vec(&state).unwrap();
        bytes.push(b'\n');
        fs::write(&snap_path, bytes).unwrap();

        let store = Store::open(&dir).unwrap();
        let v3 = store.save_version().unwrap().id;

        let d = store.diff_records(v1, v3, "users").unwrap();
        // added：先写后删——u2 仅在起始版本。
        let added: Vec<_> = d.added.iter().map(|r| r["id"].clone()).collect();
        assert_eq!(added, vec![json!("u2")]);
        // dropped：先删后写/新写入——u4、u5 仅在目标版本，按 id 字节序。
        let dropped: Vec<_> = d.dropped.iter().map(|r| r["id"].clone()).collect();
        assert_eq!(dropped, vec![json!("u4"), json!("u5")]);
        // changed：u1，before/after 为两侧完整记录。
        assert_eq!(d.changed.len(), 1);
        assert_eq!(d.changed[0].before["id"], "u1");
        assert_eq!(d.changed[0].before["age"], 36);
        assert_eq!(d.changed[0].after["age"], 37);
        assert_eq!(d.changed[0].after["role"], "admin");
        // u3 未出现在任何差异列表中。

        // 字段顺序不同但字段名/值相同：同版本比较三个列表均为空（v1 与自身）。
        let d = store.diff_records(v1, v1, "users").unwrap();
        assert!(d.added.is_empty() && d.dropped.is_empty() && d.changed.is_empty());

        // 反向比较：起始晚于目标 → 拒绝。
        assert!(matches!(
            store.diff_records(v3, v1, "users"),
            Err(DiffError::StartAfterTarget)
        ));

        // 版本 / 集合不存在。
        assert!(matches!(
            store.diff_records(999, v3, "users"),
            Err(DiffError::StartVersionNotFound)
        ));
        assert!(matches!(
            store.diff_records(v1, 999, "users"),
            Err(DiffError::TargetVersionNotFound)
        ));
        assert!(matches!(
            store.diff_records(v1, v3, "missing"),
            Err(DiffError::StartCollectionNotFound)
        ));

        // 排序验证：批量制造乱序 id，确认输出按字节序（"a" < "aa" < "b"）。
        store
            .write_batch(
                "items",
                &[
                    json!({"id": "b"}),
                    json!({"id": "a"}),
                    json!({"id": "aa"}),
                ],
            )
            .unwrap();
        let va = store.save_version().unwrap().id;
        let vb = store.save_version().unwrap().id;
        let d = store.diff_records(va, vb, "items").unwrap();
        let dropped: Vec<_> = d
            .dropped
            .iter()
            .map(|r| r["id"].as_str().unwrap())
            .collect();
        // 两版本 items 相同（同一 current 两次保存），故无差异；改为跨 v1 场景验证排序。
        assert!(dropped.is_empty());
        let d = store.diff_records(v1, vb, "items").unwrap();
        let dropped: Vec<_> = d
            .dropped
            .iter()
            .map(|r| r["id"].as_str().unwrap())
            .collect();
        assert_eq!(dropped, vec!["a", "aa", "b"]);

        fs::remove_dir_all(&dir).ok();
    }
}

