            store.diff_records(999, v3, "users"),
            Err(DiffError::StartVersionNotFound)
        ));
        assert!(matches!(
            store.diff_records(v1, 999, "users"),
            Err(DiffError::TargetVersionNotFound)
        ));
        assert!(matches!(
            store.diff_records(v1, v3, "missing"),
            Err(DiffError::StartCollectionNotFound)
        ));

        // 字节序验证：id 写入乱序（b、a、aa），起始版本保存后把集合在快照中清空，
        // 再保存目标版本，added 必须按 "a" < "aa" < "b" 输出。
        store
            .write_batch(
                "items",
                &[json!({"id": "b"}), json!({"id": "a"}), json!({"id": "aa"})],
            )
            .unwrap();
