#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LookupError {
    VersionNotFound,
    CollectionNotFound,
}

/// 版本差异查询失败：版本/集合不存在（404）或起始版本晚于目标版本（400）。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiffError {
    FromVersionNotFound,
    ToVersionNotFound,
    CollectionNotFoundInFrom,
    CollectionNotFoundInTo,
    /// 起始版本晚于目标版本（版本号随保存动作递增）。
    OutOfOrder,
}

