}

/// 同一集合在两个已保存版本之间的差异；三个列表均按主键 id 字节序升序。
#[derive(Debug, Clone, Serialize)]
pub struct DiffOutcome {
    pub from: u64,
    pub to: u64,
    pub collection: String,
    /// 仅存在于起始版本的记录（在目标版本中被删除）。
    pub added: Vec<Record>,
    /// 仅存在于目标版本的记录（新写入）。
