    for (id, after) in &to_map {
        if !from_map.contains_key(id) {
            dropped.push((*after).clone());
        }
    }

    Ok(DiffOutcome {
        from,
        to,
        collection: collection.to_string(),
        added,
        dropped,
        changed,
    })
}

