88	/// 同一集合在两个已保存版本之间的差异；三个列表均按主键 id 字节序升序。
89	#[derive(Debug, Clone, Serialize)]
90	pub struct DiffOutcome {
91	    pub from: u64,
92	    pub to: u64,
93	    pub collection: String,
