131	struct PersistedState {
132	    versions: Vec<PersistedVersion>,
133	    collections: Vec<PersistedCollection>,
134	}
135	
136	struct Inner {
137	    /// 各集合的当前数据；Vec 保存提交顺序。
138	    current: BTreeMap<String, Vec<Record>>,
139	    versions: Vec<VersionSnap>,
140	    next_id: u64,
141	    wal: fs::File,
142	}
143	
144	/// 整个服务的状态。
145	pub struct Store {
146	    inner: Mutex<Inner>,
147	    data_dir: PathBuf,
148	}
149	
150	fn now_ms() -> u64 {
