157	impl Store {
158	    /// 从数据目录加载或初始化存储，并完成崩溃恢复。
159	    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, String> {
160	        let data_dir = data_dir.as_ref().to_path_buf();
161	        fs::create_dir_all(&data_dir).map_err(|e| format!("create data dir: {e}"))?;
162	
163	        let mut current: BTreeMap<String, Vec<Record>> = BTreeMap::new();
164	        let mut versions: Vec<VersionSnap> = Vec::new();
165	
166	        // 1. 恢复最近一次快照（若存在）。
167	        let snap_path = data_dir.join("snapshot.json");
168	        if snap_path.exists() {
169	            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
170	            let state: PersistedState =
171	                serde_json::from_slice(&bytes).map_err(|e| format!("parse snapshot: {e}"))?;
172	            for c in state.collections {
173	                current.insert(c.name, c.records);
174	            }
175	            for v in state.versions {
176	                versions.push(VersionSnap {
177	                    id: v.id,
178	                    saved_at: v.saved_at,
179	                    data: v
180	                        .collections
181	                        .into_iter()
182	                        .map(|c| (c.name, c.records))
183	                        .collect(),
184	                });
185	            }
186	        }
187	        let next_id = versions.last().map(|v| v.id + 1).unwrap_or(1);
188	
189	        // 2. 重放快照之后的 WAL，并修复崩溃残留的残缺行。
190	        let wal_path = data_dir.join("wal.log");
191	        let mut valid_bytes = 0usize;
192	        if wal_path.exists() {
193	            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
194	            let mut rest = content.as_str();
195	            loop {
196	                if rest.is_empty() {
197	                    break;
198	                }
199	                let Some(nl) = rest.find('\n') else {
200	                    // 最后一行没有换行结尾：本服务的提交总是以换行结尾，故必为残缺行。
201	                    break;
202	                };
203	                let line = &rest[..nl];
204	                match serde_json::from_str::<CommitEvent>(line) {
205	                    Ok(event) => {
206	                        apply_commit(&mut current, event.collection, event.records);
207	                        valid_bytes += nl + 1;
208	                        rest = &rest[nl + 1..];
209	                    }
210	                    Err(_) => break,
211	                }
212	            }
213	            if valid_bytes < content.len() {
214	                let f = fs::OpenOptions::new()
215	                    .write(true)
216	                    .open(&wal_path)
217	                    .map_err(|e| format!("repair wal: {e}"))?;
218	                f.set_len(valid_bytes as u64)
219	                    .map_err(|e| format!("repair wal: {e}"))?;
220	                f.sync_all().ok();
221	            }
222	        }
223	
224	        // 3. 打开 WAL 供后续追加。
225	        let wal = fs::OpenOptions::new()
226	            .create(true)
227	            .append(true)
228	            .open(&wal_path)
229	            .map_err(|e| format!("open wal: {e}"))?;
230	
231	        Ok(Store {
232	            inner: Mutex::new(Inner {
233	                current,
234	                versions,
235	                next_id,
236	                wal,
237	            }),
238	            data_dir,
239	        })
240	    }
