306	
307	    // v2：新增 u3（同主键不同内容会被写入接口拒绝，故 dropped 是唯一可经接口产生的变化）。
308	    let r = request(
309	        &s.addr,
310	        "POST",
311	        "/collections/users/records",
312	        Some(r#"{"records":[{"id":"u3","name":"New","age":20}]}"#),
313	    );
314	    assert_eq!(r.status, 200);
315	    let r = request(
316	        &s.addr,
317	        "POST",
318	        "/collections/orders/records",
319	        Some(r#"{"records":[{"id":"o1","total":5}]}"#),
320	    );
321	    assert_eq!(r.status, 200);
322	    let r = request(&s.addr, "POST", "/versions", None);
323	    let v2 = r.body["id"].as_u64().unwrap();
324	
325	    // v1 → v2：u3 出现在 dropped，added/changed 为空。
326	    let r = request(
327	        &s.addr,
328	        "GET",
329	        &format!("/versions/{v1}/collections/users/diff/{v2}"),
330	        None,
331	    );
332	    assert_eq!(r.status, 200, "{}", r.body);
333	    assert_eq!(r.body["from"], v1);
334	    assert_eq!(r.body["to"], v2);
335	    assert_eq!(r.body["collection"], "users");
336	    assert_eq!(r.body["added"].as_array().unwrap().len(), 0);
337	    assert_eq!(r.body["changed"].as_array().unwrap().len(), 0);
338	    let dropped = r.body["dropped"].as_array().unwrap();
339	    assert_eq!(dropped.len(), 1);
340	    assert_eq!(dropped[0]["id"], "u3");
341	
342	    // 起始与目标相同 → 三个列表都为空。
343	    let r = request(
344	        &s.addr,
345	        "GET",
346	        &format!("/versions/{v1}/collections/users/diff/{v1}"),
347	        None,
348	    );
349	    assert_eq!(r.status, 200);
350	    assert_eq!(r.body["added"].as_array().unwrap().len(), 0);
351	    assert_eq!(r.body["dropped"].as_array().unwrap().len(), 0);
352	    assert_eq!(r.body["changed"].as_array().unwrap().len(), 0);
353	
354	    // 起始版本晚于目标版本 → 400。
355	    let r = request(
