359	        None,
360	    );
361	    assert_eq!(r.status, 400);
362	    assert!(r.body["error"].as_str().unwrap().contains("later"));
363	
364	    // 版本不存在 → 404。
365	    let r = request(
366	        &s.addr,
367	        "GET",
368	        &format!("/versions/999/collections/users/diff/{v2}"),
369	        None,
370	    );
371	    assert_eq!(r.status, 404);
372	    assert!(r.body["error"].as_str().unwrap().contains("version 999"));
373	    let r = request(
